import React, {
    ChangeEvent,
    FC,
    ClipboardEvent,
    useCallback,
    FocusEvent,
    useMemo,
    useState,
    useRef,
    useId,
} from 'react';
import InputMask from '@mona-health/react-input-mask';
import * as S from './styles';
import { PhoneInputLogic } from './phoneInputLogic';
import { useValidateInitialValue } from './hooks/useValidateInitialValue';
import { RUS_COUNTRY_CODE, TSupportedCountries } from './types';
import { useInputFocus } from '../../../hooks/useInputFocus';
import { InputLabel } from '../InputLabel';
import { PureInput, TProps as TPureInputProps } from '../PureInput';
import { CountrySelect, TProps as TCountrySelectProps } from '../CountrySelect';
import { useMobile } from '../../../hooks/useMedia';
import { MODERN_STYLE_SIZE_PARAMS_MAP, TSizes } from '../constants';
import { ModernPlaceholder } from '../ModernPlaceholder';
import { useInputStyles } from '../_hooks/useInputStyles';

type TFieldProps = Pick<TPureInputProps, 'name' | 'onBlur' | 'onFocus'> & {
    value: string;
    onChange: (value: string) => void;
    hasError?: boolean;
};

type TControlProps = Pick<TPureInputProps, 'disabled' | 'id' | 'autoFocus' | 'useModernStyles'> & {
    label: string;
    countrySelectProps?: Pick<TCountrySelectProps, 'selectedLabel' | 'placeholder'>;
    onCountryChange?: (countryCode: string) => void;
    countries?: Array<{ label: string; value: TSupportedCountries }>;
    pureInputProps?: Pick<TPureInputProps, 'paddingTop' | 'paddingBottom' | 'autoFocus'>;
    size?: TSizes;
    isSupportCityRusPhoneNumber?: boolean;
    isInnerErrorHighlight?: boolean;
    required?: boolean;
};

export type TProps = TControlProps & TFieldProps;

export const PhoneInput: FC<TProps> = ({
    onBlur,
    name,
    onFocus,
    countrySelectProps,
    value,
    onChange,
    hasError,
    label,
    disabled,
    id,
    countries,
    onCountryChange,
    pureInputProps,
    size,
    autoFocus,
    isSupportCityRusPhoneNumber = false,
    isInnerErrorHighlight = true,
    required = false,
    useModernStyles = false,
}) => {
    const inputRef = useRef<HTMLInputElement>();
    const isMobile = useMobile();

    const fallbackId = useId();
    const inputId = id ?? fallbackId;

    const phoneInputLogic = useMemo(
        () => new PhoneInputLogic(isSupportCityRusPhoneNumber),
        [isSupportCityRusPhoneNumber],
    );

    const countrySelectOptions = useMemo(
        () => phoneInputLogic.getCountriesSelectOptions(countries),
        [countries, phoneInputLogic],
    );
    const isHaveSelectCountries = useMemo(
        () => phoneInputLogic.getIsHaveCountriesSelectOptions(countrySelectOptions),
        [countrySelectOptions, phoneInputLogic],
    );
    const currentCountriesPhoneRules = useMemo(
        () => phoneInputLogic.getCountriesPhoneRulesBySelectOptions(countrySelectOptions),
        [countrySelectOptions, phoneInputLogic],
    );

    const {
        inFocus,
        handleFocus: focusHandler,
        handleBlur: blurHandler,
    } = useInputFocus({ onFocus, onBlur });

    const [isHaveInputError, setIsHaveInputError] = useState(false);
    const [isFirstBlur, setIsFirstBlur] = useState(true);

    const [inputValue, setInputValue] = useState(value);
    const [country, setCountry] = useState(RUS_COUNTRY_CODE);

    const { inputLabel, paddingAndVariantOptions, isHideModernPlaceholder, fieldSize } = useInputStyles({
        isHaveValue: !!inputValue,
        useModernStyles,
        size,
        label,
        inFocus,
        placeholder: '',
        required,
    });

    const handleChangeCountry = useCallback(
        (countryCode: string) => {
            setCountry(countryCode);
            if (onCountryChange) {
                onCountryChange(countryCode);
            }
        },
        [onCountryChange],
    );

    const handleInitialValid = useCallback(
        (currentInputValue: string, countryCode: string) => {
            onChange(currentInputValue);
            setIsHaveInputError(false);
            setCountry(countryCode);
        },
        [onChange],
    );

    const handleInitialUnValid = useCallback(
        (countryCode: string) => {
            onChange('');
            setIsHaveInputError(true);
            setCountry(countryCode);
        },
        [onChange],
    );

    useValidateInitialValue(
        phoneInputLogic,
        value,
        currentCountriesPhoneRules,
        handleInitialValid,
        handleInitialUnValid,
    );

    const getNewCountryByInputValue = useCallback(
        (currentValue: string) => {
            const currentCountry = currentCountriesPhoneRules[country];
            const newCountry = Object.entries(currentCountriesPhoneRules).find((item) =>
                phoneInputLogic.getIsHaveStartSequenceInString(currentValue, item[1].startSubsequence),
            );

            const isNeedChangeCountry = phoneInputLogic.getIsNeedChangeCountry(
                currentValue,
                currentCountry,
                newCountry,
            );
            const isNeedAndCanChangeCountry = isNeedChangeCountry && !!newCountry;
            if (isNeedAndCanChangeCountry) {
                handleChangeCountry(newCountry[0]);
            }

            return isNeedAndCanChangeCountry ? newCountry[1] : currentCountry;
        },
        [country, currentCountriesPhoneRules, handleChangeCountry, phoneInputLogic],
    );

    const getIsValidValue = useCallback(
        (currentValue: string) => {
            const currentCountry = getNewCountryByInputValue(currentValue);

            return phoneInputLogic.getIsValidPhoneInputByCountry(currentValue, currentCountry);
        },
        [getNewCountryByInputValue, phoneInputLogic],
    );

    const handleInputValueChange = useCallback(
        (
            currentInputValue: string,
            event?: ChangeEvent<HTMLInputElement> | ClipboardEvent<HTMLInputElement>,
        ) => {
            const notFormattedValue = phoneInputLogic.getOnlyNumbersFromString(currentInputValue);
            const moveCaret = event ? phoneInputLogic.moveCaretByValue(event) : undefined;
            const intermediateValue =
                country === RUS_COUNTRY_CODE
                    ? phoneInputLogic.formatRusPhoneToUnifiedView(notFormattedValue, moveCaret)
                    : notFormattedValue;

            const isValidInputValue = getIsValidValue(intermediateValue);
            setIsHaveInputError(!isValidInputValue);
            onChange(isValidInputValue ? intermediateValue : '');
            setInputValue(intermediateValue);
        },
        [country, getIsValidValue, onChange, phoneInputLogic],
    );

    const handleChange = useCallback(
        (event: ChangeEvent<HTMLInputElement>) => {
            handleInputValueChange(event.target.value, event);
        },
        [handleInputValueChange],
    );

    const handleBlur = useCallback(
        (event: FocusEvent<HTMLInputElement>) => {
            blurHandler(event);
            if (isFirstBlur) {
                setIsFirstBlur(false);
            }
        },
        [isFirstBlur, blurHandler],
    );

    const handleCountryChange = useCallback(
        (countryValue: string) => {
            handleChangeCountry(countryValue);
            const currentCountry = currentCountriesPhoneRules[countryValue];
            const isValidInputValue = phoneInputLogic.getIsValidPhoneInputByCountry(
                inputValue,
                currentCountry,
            );
            setIsFirstBlur(false);
            setIsHaveInputError(!isValidInputValue);
            onChange(isValidInputValue ? inputValue : '');
            setTimeout(() => {
                inputRef.current?.focus();
            }, 0);
        },
        [currentCountriesPhoneRules, handleChangeCountry, inputValue, onChange, phoneInputLogic],
    );

    const handlePaste = useCallback(
        (event: ClipboardEvent<HTMLInputElement>) => {
            event.preventDefault();

            const pasteText = event.clipboardData.getData('Text').trim();
            handleInputValueChange(pasteText, event);
        },
        [handleInputValueChange],
    );

    const hasPureInputError = useMemo(() => {
        if (hasError) return true;

        if (isFirstBlur) return false;

        if (isInnerErrorHighlight) return isHaveInputError;

        return false;
    }, [hasError, isFirstBlur, isHaveInputError, isInnerErrorHighlight]);

    const inputPlaceholder = useMemo(() => {
        if (useModernStyles) {
            return undefined;
        } else {
            return currentCountriesPhoneRules[country].placeholder;
        }
    }, [country, currentCountriesPhoneRules, useModernStyles]);

    const modernPlaceholderText = label || currentCountriesPhoneRules[country].placeholder;

    return (
        <InputLabel
            inFocus={inFocus}
            label={inputLabel}
            disabled={disabled}
            required={required}
            useModernStyles={useModernStyles}
            size={fieldSize}
            left={isHaveSelectCountries && useModernStyles ? 65 : undefined}
            htmlFor={inputId}
        >
            <S.InputLabelContent>
                {useModernStyles && (
                    <ModernPlaceholder
                        visible={!isHideModernPlaceholder}
                        paddingLeft={isHaveSelectCountries ? 75 : 18}
                        paddingTop={MODERN_STYLE_SIZE_PARAMS_MAP[fieldSize].$placeholderPaddingTop}
                        size={fieldSize}
                        required={required}
                    >
                        {modernPlaceholderText}
                    </ModernPlaceholder>
                )}
                {!!countrySelectOptions?.length && (
                    <S.InputLabelFloatWrapper>
                        <S.CountrySelectWrapper>
                            <CountrySelect
                                minWidth={isMobile ? '100%' : '350px'}
                                options={countrySelectOptions}
                                onChange={handleCountryChange}
                                value={country}
                                placeholder={countrySelectProps?.placeholder || ''}
                                positionVertical={16}
                                positionRight="0"
                                positionLeft="-20px"
                                disabled={disabled}
                                selectedLabel={countrySelectProps?.selectedLabel || ''}
                            />
                        </S.CountrySelectWrapper>
                    </S.InputLabelFloatWrapper>
                )}
                <InputMask
                    value={inputValue}
                    onFocus={focusHandler}
                    onBlur={handleBlur}
                    onChange={handleChange}
                    mask={currentCountriesPhoneRules[country].mask}
                    maskPlaceholder={null}
                    disabled={disabled}
                    onPaste={handlePaste}
                    placeholder={inputPlaceholder}
                    ref={inputRef}
                >
                    <PureInput
                        id={inputId}
                        aria-label={label && !inputLabel ? label : undefined}
                        hasError={hasPureInputError}
                        inFocus={inFocus}
                        name={name}
                        paddingLeft={isHaveSelectCountries ? 75 : 18}
                        // for disable autocomplete
                        autoComplete={'new-password'}
                        inputMode="numeric"
                        // eslint-disable-next-line jsx-a11y/no-autofocus -- проп прокидывается потребителю, решение об автофокусе за ним
                        autoFocus={autoFocus}
                        {...paddingAndVariantOptions}
                        useModernStyles={useModernStyles}
                        {...pureInputProps}
                    />
                </InputMask>
            </S.InputLabelContent>
        </InputLabel>
    );
};
